<script setup lang="ts">
  import { reactive, watch } from 'vue';
  import HoverTransition from '@registry/new-york/hover-transition/HoverTransition.vue';
  import {
    hoverTransitionDirections,
    hoverTransitionEffects,
  } from '@registry/new-york/hover-transition/hover-transition-layers.ts';
  import type {
    HoverTransitionDirection,
    HoverTransitionEffect,
  } from '@registry/new-york/hover-transition/types';
  import type { Pane } from 'tweakpane';

  // 4×2 portrait sprite, one cell per teammate (inlined so the demo needs no public asset).
  const TEAM_SPRITE =
    'data:image/webp;base64,';

  const PEOPLE = [
    {
      id: 'tom',
      name: 'Tom Mathews',
      role: 'CEO',
      bio: 'Leading the studio’s mission to blend regional creativity with AI automation that helps businesses work smarter and scale faster.',
      position: '0% 0%',
    },
    {
      id: 'andrew',
      name: 'Andrew Michel',
      role: 'COO',
      bio: 'Turning ambitious ideas into focused systems, strong teams, and repeatable operations that keep every project moving forward.',
      position: '33.333% 0%',
    },
    {
      id: 'james',
      name: 'James Smith',
      role: 'CTO',
      bio: 'Building reliable AI products that connect thoughtful engineering with simple, human-centered digital experiences.',
      position: '66.667% 0%',
    },
    {
      id: 'marlen',
      name: 'Marlen',
      role: 'CMO',
      bio: 'Shaping clear brand stories and campaigns that turn attention into lasting relationships between people and products.',
      position: '100% 0%',
    },
    {
      id: 'sophie',
      name: 'Sophie Laura',
      role: 'Strategy Director',
      bio: 'Finding the sharpest path through complex challenges and translating research into confident creative direction.',
      position: '0% 100%',
    },
    {
      id: 'daniel',
      name: 'Daniel Reed',
      role: 'Product Director',
      bio: 'Guiding products from first sketch to launch with a practical balance of customer insight, craft, and commercial impact.',
      position: '33.333% 100%',
    },
    {
      id: 'amina',
      name: 'Amina Yusuf',
      role: 'Creative Director',
      bio: 'Creating expressive visual systems where culture, technology, and meticulous art direction meet with purpose.',
      position: '66.667% 100%',
    },
    {
      id: 'liam',
      name: 'Liam Woods',
      role: 'Studio Partner',
      bio: 'Helping clients turn bold goals into enduring collaborations, measurable growth, and work the whole team is proud to share.',
      position: '100% 100%',
    },
  ];

  const EASINGS: Record<string, string> = {
    smooth: 'cubic-bezier(0.22, 1, 0.36, 1)',
    soft: 'cubic-bezier(0.4, 0, 0.2, 1)',
    snappy: 'cubic-bezier(0.16, 1, 0.3, 1)',
  };

  // Per-card settings, indexed like PEOPLE (upstream playground defaults).
  const effects = reactive<HoverTransitionEffect[]>([
    'morph',
    'diagonal',
    'strips',
    'ripple',
    'curtain',
    'slide',
    'wipe',
    'parallax',
  ]);
  const directions = reactive<HoverTransitionDirection[]>([
    'center',
    'top-left',
    'bottom',
    'center',
    'top',
    'left',
    'bottom-right',
    'top-right',
  ]);
  const colors = reactive<string[]>([
    '#dfff5f',
    '#ff795f',
    '#7c8cff',
    '#ff9bcb',
    '#56d6b0',
    '#ffc857',
    '#bba7ff',
    '#62d6e8',
  ]);

  const params = reactive({
    card: 0,
    effect: effects[0] ?? 'morph',
    direction: directions[0] ?? 'center',
    color: colors[0] ?? '#dfff5f',
    duration: 0.72,
    easing: 'smooth',
  });

  let paneRef: Pane | null = null;

  function loadCard(index: number) {
    params.effect = effects[index] ?? 'wipe';
    params.direction = directions[index] ?? 'right';
    params.color = colors[index] ?? '#dfff5f';
    paneRef?.refresh();
  }

  function selectCard(index: number) {
    params.card = index;
  }

  watch(() => params.card, loadCard);

  watch(
    [() => params.effect, () => params.direction, () => params.color],
    ([effect, direction, color]) => {
      effects[params.card] = effect;
      directions[params.card] = direction;
      colors[params.card] = color;
    },
  );

  function easingFor(name: string): string {
    return EASINGS[name] ?? 'cubic-bezier(0.22, 1, 0.36, 1)';
  }

  function toOptions(values: readonly string[]): Record<string, string> {
    return Object.fromEntries(values.map((value) => [value, value]));
  }

  function onPaneCreated(pane: Pane) {
    paneRef = pane;
    pane.addBinding(params, 'card', {
      options: Object.fromEntries(
        PEOPLE.map((person, index) => [person.name, index]),
      ),
    });
    pane.addBinding(params, 'effect', {
      options: toOptions(hoverTransitionEffects),
    });
    pane.addBinding(params, 'direction', {
      options: toOptions(hoverTransitionDirections),
    });
    pane.addBinding(params, 'color', { label: 'hover-color' });
    pane.addBinding(params, 'duration', { min: 0.15, max: 1.8, step: 0.05 });
    pane.addBinding(params, 'easing', {
      options: toOptions(Object.keys(EASINGS)),
    });
  }
</script>

<template>
  <ComponentDemo
    :code="`<script setup lang=&quot;ts&quot;>
