        </p>
        <p class=&quot;font-semibold&quot;>Maya Chen</p>
      </article>
    </template>
  </HoverTransition>
</template>`"
  >
    <div
      class="relative flex size-full min-h-130 items-center overflow-hidden py-8 @container-size sm:py-12"
    >
      <div
        class="flex w-full snap-x snap-mandatory scroll-px-4 gap-3 overflow-x-auto overscroll-x-contain scroll-smooth px-4 py-2 scrollbar-none sm:scroll-px-6 sm:gap-4 sm:px-6 lg:scroll-px-8 lg:px-8 [&::-webkit-scrollbar]:hidden"
        aria-label="Team hover transitions"
      >
        <HoverTransition
          v-for="(person, index) in PEOPLE"
          :key="person.id"
          :effect="effects[index]"
          :direction="directions[index]"
          :duration="params.duration"
          :easing="easingFor(params.easing)"
          :label="`${person.name}, ${person.role}`"
          class="group/hover-card @container aspect-[.795] w-[clamp(260px,38cqw,390px)] shrink-0 snap-start rounded-[clamp(18px,2cqw,26px)] bg-[#f8f8f5] ring-1 ring-black/10 dark:ring-white/10"
          @click="selectCard(index)"
        >
          <article
            class="relative size-full overflow-hidden bg-[#f8f8f5] bg-size-[400%_200%] bg-no-repeat"
            :style="{
              backgroundImage: `url('${TEAM_SPRITE}')`,
              backgroundPosition: person.position,
            }"
          >
            <div
              class="absolute inset-x-0 bottom-0 px-[clamp(10px,5cqw,18px)] pb-[clamp(10px,5cqw,18px)] text-[#151515]"
            >
              <p
                class="text-[clamp(14px,7cqw,24px)] leading-none font-medium tracking-[-0.04em]"
              >
                {{ person.name }}
              </p>
              <p
                class="mt-1 text-[clamp(9px,3.2cqw,12px)] leading-none tracking-[-0.02em] text-black/60 uppercase"
              >
                {{ person.role }}
              </p>
            </div>
            <div
              class="absolute inset-x-[clamp(10px,5cqw,18px)] top-[clamp(10px,5cqw,18px)] flex justify-end font-mono text-[clamp(8px,3cqw,10px)] tracking-[0.08em] text-black/55 uppercase"
            >
              <span>{{ effects[index] }}</span>
            </div>
          </article>
          <template #hover>
